package com.kovian.finance.asset.domain; import jakarta.persistence.*; import java.math.*; import java.time.*; import java.util.*; @Entity @Table(name="financial_assets") public class FinancialAsset { @Id @GeneratedValue(strategy=GenerationType.UUID) UUID id; @Column(name="owner_id",nullable=false) UUID ownerId; @Column(nullable=false) String name; @Column(name="asset_type",nullable=false) String assetType; @Column(name="acquisition_value",nullable=false,precision=19,scale=4) BigDecimal acquisitionValue; @Column(name="current_value",nullable=false,precision=19,scale=4) BigDecimal currentValue; @Enumerated(EnumType.STRING) @Column(nullable=false) AssetLiquidity liquidity; @Column(nullable=false) boolean active=true; @Column(name="updated_at",nullable=false) OffsetDateTime updatedAt=OffsetDateTime.now(); protected FinancialAsset(){} public FinancialAsset(UUID o,String n,String t,BigDecimal a,BigDecimal c,AssetLiquidity l){if(o==null||n==null||n.isBlank()||a==null||a.signum()<0||c==null||c.signum()<0)throw new IllegalArgumentException("Invalid asset");ownerId=o;name=n.trim();assetType=t;acquisitionValue=a;currentValue=c;liquidity=l;} public UUID getOwnerId(){return ownerId;} public BigDecimal getCurrentValue(){return currentValue;} public void updateValue(BigDecimal v){if(v==null||v.signum()<0)throw new IllegalArgumentException("Invalid asset value");currentValue=v;updatedAt=OffsetDateTime.now();}}